export interface DataScan_DataQualitySpec_PostScanActions_NotificationReport {
  /** This trigger is triggered whenever a scan job run ends, regardless of the result. */
  jobEndTrigger?: unknown | Computed<unknown>;
  /** This trigger is triggered when the scan job itself fails, regardless of the result. */
  jobFailureTrigger?: unknown | Computed<unknown>;
  /** The individuals or groups who are designated to receive notifications upon triggers. */
  recipients?: DataScan_DataQualitySpec_PostScanActions_NotificationReport_Recipients | Computed<DataScan_DataQualitySpec_PostScanActions_NotificationReport_Recipients>;
  /** This trigger is triggered when the DQ score in the job result is less than a specified input score. */
  scoreThresholdTrigger?: DataScan_DataQualitySpec_PostScanActions_NotificationReport_ScoreThresholdTrigger | Computed<DataScan_DataQualitySpec_PostScanActions_NotificationReport_ScoreThresholdTrigger>;
}

